"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["33059"],{12409(e){e.exports=JSON.parse('{"id":"FIN-573","slug":"basic-eps","term":"Basic EPS","also_known_as":[],"difficulty":"Intermediate","definition":"Basic EPS is a company\'s net income attributable to ordinary shareholders divided by the weighted average number of ordinary shares outstanding during the period.","explanation":["Basic earnings per share uses the actual shares in issue, without considering shares that might be created in future from stock options, warrants or convertible securities.","Two adjustments are important. First, any dividends owed to preferred shareholders are subtracted from net income, because that profit does not belong to ordinary shareholders. Second, the number of shares is a weighted average, reflecting how long each share was outstanding during the period.","For example, a company with 4 million shares for the first half of the year issues 2 million more at mid-year, so it has 6 million for the second half. Its weighted average share count is 5 million. If net income attributable to ordinary shareholders is 10 million, basic EPS is 2.00.","Basic EPS gives a straightforward measure of profit per share based on shares that actually exist. Companies also report diluted EPS, which assumes that potential shares are created and therefore gives a more cautious figure. When the two numbers are far apart, it signals that significant dilution could occur in future."],"note":"","total":1500,"prev":{"slug":"basel-accords","term":"Basel Accords"},"next":{"slug":"basis","term":"Basis"}}')}}]);